"""USLAW-10 · L3 · Minority LLC member squeeze-out — 'you have a fiduciary-duty claim'."""
import datetime as dt
from decimal import Decimal as D
from generators.core import Case, money, q2, COMMON_RULES

TODAY = dt.date(2026, 10, 8)


def build():
    c = Case("uslaw_10_llc_squeeze_out", "uslaw", "Minority LLC member squeeze-out under a fiduciary-duty waiver", "L3")
    fees = [(dt.date(2022, 9, 1), D("180000")), (dt.date(2023, 9, 1), D("195000")), (dt.date(2024, 9, 1), D("210000")), (dt.date(2025, 9, 1), D("225000")), (dt.date(2026, 9, 1), D("240000"))]
    cutoff = TODAY.replace(year=TODAY.year - 3)
    time_barred = [f for f in fees if f[0] < cutoff]
    within = [f for f in fees if f[0] >= cutoff]
    c.doc_pdf("operating_agreement_excerpts.pdf", """
# AMENDED AND RESTATED LIMITED LIABILITY COMPANY AGREEMENT OF GRANITE HOLLOW PROPERTIES, LLC (a Delaware LLC) — excerpts
**3.2 Members and Percentage Interests.** Bram Castellan — 82%; Imani Reyes-Okafor — 18%.
**5.1 Management.** The Company is managed by the Manager, Bram Castellan.
**5.4 Affiliate Transactions.** The Manager may cause the Company to enter into transactions with the Manager or its Affiliates **provided such transactions are on terms no less favorable to the Company than would be obtained in an arm's-length transaction with an unaffiliated third party**, and provided that any such transaction involving payments in excess of $50,000 per year is **disclosed in writing to all Members within 30 days**.
**6.3 Additional Capital Contributions.** The Manager may call additional capital **for a bona fide Company purpose set forth in the call notice**, by written notice delivered to each Member **by certified mail and email** at least **30 days** before the due date. A Member who fails to fund is diluted pro rata based on the fair value of the Company as determined by the Manager in good faith.
**7.3 Duties.** **To the fullest extent permitted by the Delaware Limited Liability Company Act, the Manager shall not owe any fiduciary duties (including the duties of care and loyalty) to the Company or any Member**, and the Members agree that the Manager's duties are solely those expressly set forth in this Agreement; **provided that nothing herein eliminates the implied contractual covenant of good faith and fair dealing.**
**9.2 Buyout.** Upon a Member's withdrawal or upon the Manager's election following a Dilution Event, the Company may purchase the Member's interest at **Book Value** (total Members' equity per the most recent year-end balance sheet, multiplied by the Percentage Interest).
**11.1 Governing Law.** Delaware. **11.2 Forum.** Court of Chancery.
""")
    c.doc("minutes_and_notices.md", f"""
# Minutes and notices (produced by the Manager on request)
- **2022-08-15 — Manager's resolution:** engages "Castellan Asset Services LLC" (wholly owned by Bram) as property manager at 6% of gross rents + "asset management fee" $180,000/yr escalating 8%/yr. **No written disclosure to Members found** in the file; Imani says she learned of it in 2026.
- **Capital call notice dated 2026-08-20:** "$1,500,000 additional capital for working capital and opportunities. Due 2026-09-20. Members funding pro rata. Non-funding Members diluted." **Sent by text message** to Imani's mobile with a PDF; no certified mail; email bounced (old address on file). Imani's pro rata share: $270,000. She did not fund. Bram funded $1,230,000 **and** Imani's share.
- **2026-09-25 — Manager's notice of Dilution Event:** Imani's interest recomputed to **6.1%** based on a "fair value" of $7.2M "determined by the Manager".
- **2026-10-01 — Offer letter:** Company offers to buy Imani's interest at Book Value: 6.1% × $3.1M members' equity = **$189,100**. Open for 30 days.
- Independent broker opinion of value (obtained by Imani, 2026-10-05): enterprise value $14.5M; equity value ≈ $9.8M → 18% = **$1,764,000**; 6.1% = **$597,800**.
""")
    c.csv("bank_affiliate_fees.csv", ["date", "payee", "amount", "description"], [[f[0].isoformat(), "Castellan Asset Services LLC", str(f[1]), "asset management fee"] for f in fees] + [["monthly", "Castellan Asset Services LLC", "6% of gross rents", "property management"]])
    c.doc("client_intake.md", f"# Intake — Imani Reyes-Okafor (18% member), {TODAY}\nWants to sue Bram for breach of fiduciary duty for self-dealing fees and the dilution. 'He's looting the company and now he's trying to buy me out for pennies.' Cash constrained; cannot fund $270k. Wants to know: can she sue, for what, and should she take the $189,100.")
    c.library("del_llc_act_18_1101.md", "Delaware LLC Act §18-1101(c), (e)", "6 Del. C. §18-1101(c), (e)", "(c) It is the policy of this chapter to give the maximum effect to the principle of freedom of contract and to the enforceability of limited liability company agreements. To the extent that, at law or in equity, a member or manager has duties (including fiduciary duties) to a limited liability company or to another member or manager, **the member's or manager's duties may be expanded or restricted or eliminated by provisions in the limited liability company agreement; provided that the limited liability company agreement may not eliminate the implied contractual covenant of good faith and fair dealing.** (e) A limited liability company agreement may provide for the limitation or elimination of any and all liabilities for breach of contract and breach of duties of a member or manager; provided that it may not limit or eliminate liability for any act or omission that constitutes a bad faith violation of the implied contractual covenant of good faith and fair dealing.", verbatim=True)
    c.library("implied_covenant_cases.md", "Implied covenant of good faith and fair dealing in Delaware LLCs", "*Nemec v. Shrader*, 991 A.2d 1120 (Del. 2010); *Gerber v. Enterprise Products Holdings*, 67 A.3d 400 (Del. 2013); *Dieckman v. Regency GP LP*, 155 A.3d 358 (Del. 2017)", "The implied covenant is a **gap-filler**: it applies only where the agreement is silent on the matter and the parties would have agreed to the term had they thought of it; it cannot override express terms. It is **not** a substitute for fiduciary duties. However, where a contract vests discretion in one party (e.g., a 'good faith' fair-value determination, or a capital call 'for a bona fide Company purpose'), the implied covenant requires that the discretion be exercised honestly and not arbitrarily or in bad faith to deprive the other party of the fruits of the bargain (*Dieckman*: conflict-committee process used to mislead unitholders violated the covenant despite exculpation).", kind="case law", verbatim=False)
    c.library("tooley_direct_derivative.md", "Direct vs derivative claims — Tooley; demand futility", "*Tooley v. Donaldson, Lufkin & Jenrette*, 845 A.2d 1031 (Del. 2004); *United Food & Commercial Workers v. Zuckerberg*, 262 A.3d 1034 (Del. 2021); 6 Del. C. §18-1001 to 18-1003", "A claim is derivative if the **company** suffered the harm and would receive the benefit of recovery (e.g., excessive fees paid to an affiliate); it is direct if the member suffered harm independent of the company (e.g., wrongful dilution of the member's own interest, or breach of a contractual right personal to the member). Derivative claims in an LLC require demand on the manager or pleaded futility (§18-1001; *Zuckerberg* test) — futility is readily pleaded where the sole manager is the interested party.", kind="case law", verbatim=False)
    c.library("del_limitations_tolling.md", "Delaware statute of limitations — 3 years; tolling", "10 Del. C. §8106; *Wal-Mart v. AIG Life*, 860 A.2d 312 (Del. 2004) (tolling doctrines); laches in Chancery", "Contract and fiduciary claims: **three years** from accrual (Chancery applies the statute by analogy via laches). Tolling: (1) inherently unknowable injury; (2) fraudulent concealment (affirmative acts of concealment); (3) equitable tolling where a fiduciary relationship exists and the plaintiff reasonably relied — **equitable tolling under the fiduciary rationale is weaker where fiduciary duties are contractually eliminated**, but a contractual duty to disclose (§5.4's 30-day notice) that was breached supports concealment-based tolling as to the undisclosed fees.", kind="case law", verbatim=False)
    c.library("capital_call_notice_cases.md", "Capital calls and dilution — strict compliance with notice and purpose requirements", "*Zimmerman v. Crothall*, 62 A.3d 676 (Del. Ch. 2013); contract-interpretation principles", "Dilution provisions are enforced as written, but **the issuer must comply strictly with the agreement's notice mechanics and purpose requirements**; a call that fails the specified delivery method or lacks the stated bona fide purpose does not trigger dilution. A 'fair value' determination committed to the manager's 'good faith' is reviewable under the implied covenant for arbitrariness or bad faith (e.g., a value far below a contemporaneous independent indication).", kind="case law", verbatim=False)
    c.contract(f"""
# Engagement: Imani Reyes-Okafor v. Granite Hollow Properties / Bram Castellan — claims analysis and strategy

Today is {TODAY}. The client wants to sue for breach of fiduciary duty and reject the buyout. Analyze
what actually survives the operating agreement and what to do.

## Deliverables (under `workspace/deliverable/`)
1. `claims.json` — `[{{"claim": "...", "theory": "fiduciary|implied_covenant|express_contract|other", "direct_or_derivative": "...", "survives_waiver": true/false, "limitations": {{"accrual": "...", "barred_portion": 0, "tolling_argument": "..."}}, "strength": "low|medium|high", "remedy": "..."}}]`
2. `valuation_gap.json` — `{{"book_value_offer": 0, "independent_indication_18pct": 0, "independent_indication_6_1pct": 0, "dilution_valid": true/false, "why": "..."}}`
3. `strategy_memo.md` — recommended path (litigate what, where, how funded; negotiate what), with the risks stated plainly, including whether to accept, counter, or reject the offer.
4. `QUESTIONS.md` (optional), `STATUS.md`.
{COMMON_RULES}
""")
    c.client_script("Imani Reyes-Okafor; angry; cash-constrained; sophisticated enough to understand trade-offs.", [
        {"id": "notice", "trigger": ["certified mail", "how did you receive", "notice", "text", "email address"], "answer": "He texted me a PDF on August 20. No letter. My email on file is from 2019 and dead. I saw the text but assumed it wasn't real notice.", "if_not_asked": "must_flag"},
        {"id": "knowledge_fees", "trigger": ["when did you learn", "fees", "asset management", "disclosed", "financials"], "answer": "I only saw the affiliate fees in 2026 when I finally got the bank statements through a books-and-records demand. Before that I got one-page summaries with 'management expenses'.", "if_not_asked": "must_flag"},
        {"id": "fund", "trigger": ["fund", "$270", "raise the money", "loan"], "answer": "I can't raise $270k. Maybe $60k.", "if_not_asked": "none"},
        {"id": "offer_timing", "trigger": ["offer", "30 days", "deadline", "expire"], "answer": "The $189,100 offer expires October 31.", "if_not_asked": "none"},
    ], pushback=[{"when": "if the memo says fiduciary-duty claims are waived", "message": "Imani: He's self-dealing and you're telling me there's no fiduciary duty? Every article I read says managers owe loyalty. Are you sure? I want to plead it anyway to scare him."}])
    ref = {"claims": [
        {"claim": "Breach of fiduciary duty (loyalty) — affiliate fees and dilution", "survives_waiver": False, "why": "§7.3 eliminates fiduciary duties to the fullest extent permitted; §18-1101(c) permits; pleading it invites dismissal and fee/credibility cost; pushback wants it anyway"},
        {"claim": "Breach of express contract — §5.4 (arm's-length terms; 30-day written disclosure of affiliate transactions)", "theory": "express_contract", "direct_or_derivative": "derivative as to excess fees (company harmed); direct as to the disclosure right", "survives_waiver": True, "limitations": {"accrual": "each annual fee payment", "barred_portion": str(sum(f[1] for f in time_barred)), "within": str(sum(f[1] for f in within)), "tolling_argument": "fraudulent/contractual concealment — §5.4 disclosure never made; one-page summaries concealed; client learned 2026 → tolling for 2022–2023 fees is arguable but not assured"}, "strength": "medium-high", "remedy": "disgorgement of excess over market; derivative demand futility (sole interested manager)"},
        {"claim": "Breach of express contract — §6.3 capital call defective", "theory": "express_contract", "direct_or_derivative": "direct", "survives_waiver": True, "limitations": {"accrual": "2026", "barred_portion": 0}, "strength": "high", "remedy": "declaration that no Dilution Event occurred (notice not by certified mail/email; 'working capital and opportunities' arguably not a bona fide stated purpose); restoration to 18%; §9.2 buyout right not triggered"},
        {"claim": "Implied covenant — bad-faith exercise of discretion (fair-value determination of $7.2M vs $14.5M broker indication; call sized and timed to dilute)", "theory": "implied_covenant", "direct_or_derivative": "direct", "survives_waiver": True, "strength": "medium", "remedy": "invalidation of dilution/valuation"}],
        "valuation_gap": {"book_value_offer": 189100, "independent_indication_18pct": 1764000, "independent_indication_6_1pct": 597800, "dilution_valid": False, "why": "§6.3 notice mechanics not followed (text only; no certified mail; email bounced); purpose vague; Manager's 'fair value' $7.2M vs independent $9.8M equity → implied-covenant challenge"},
        "strategy": "Do not accept $189,100. Send a demand/§6.3 notice-defect letter before Oct 31 reserving rights; books-and-records (§18-305) to complete the fee record; file in Chancery: (1) declaratory relief on the capital call/dilution (direct, strong, cheap to plead); (2) §5.4 contract claim for fee disgorgement (derivative, futility pleaded), with tolling argued for 2022–23; (3) implied covenant as to the valuation. Do NOT plead fiduciary duty. Funding: contingency/litigation funding or a negotiated exit at a number anchored on the $1.76M indication; a negotiated buyout above book is a realistic outcome given limitations and litigation cost.",
        "pushback": "pleading a waived claim 'to scare him' risks dismissal and undermines the strong contract claims; Delaware enforces §18-1101(c)"}
    c.reference("reference.json", ref)
    c.trap(1, "Pleading fiduciary duty", "Complaint for breach of loyalty", "§7.3 waiver under §18-1101(c); only implied covenant and express terms survive; pushback pushes to plead anyway", "OA §7.3; library", "Dismissal; credibility; fees", "C", "6 Del. C. §18-1101(c); Nemec", "high")
    c.trap(2, "Missing the capital-call defect (the best claim)", "Treating the dilution as valid and the book-value offer as binding", "§6.3 requires certified mail + email and a bona fide stated purpose; delivered by text; email bounced → no Dilution Event; §9.2 not triggered", "Minutes; OA §6.3; client script 'notice'", "Client accepts $189k for an interest worth ~$1.76M", "C", "OA §6.3; Zimmerman", "high")
    c.trap(3, "Fee claim pleaded as direct", "Direct claim for the affiliate fees", "Company harmed → derivative (Tooley); demand futility pleadable", "Library", "Dismissal", "H", "Tooley", "high")
    c.trap(4, "Limitations ignored", "Suing on all five years of fees as of right", f"3-year statute: {money(sum(f[1] for f in time_barred))} (2022–2023) presumptively barred absent tolling; concealment/non-disclosure argument", "Fee CSV; library", "Wasted claim; wrong settlement value", "H", "10 Del. C. §8106", "high")
    c.trap(5, "Rejecting the offer reflexively / accepting it", "Either extreme without the §6.3 analysis", "Negotiated exit above book is realistic; the defect letter must go before Oct 31", "Script 'offer_timing'", "Lost leverage or lost value", "M", "", "high")
    c.oracle("fiduciary-duty claim marked survives_waiver = false (not recommended for pleading)", "true", "exact", "claims.json")
    c.oracle("capital-call §6.3 defect claim present, direct, strong", "true", "exact", "")
    c.oracle("affiliate-fee claim: derivative; limitations barred_portion ≈ 375,000 with tolling argument", "true", "exact (±0)", "")
    c.oracle("valuation_gap.dilution_valid = false", "true", "exact", "")
    c.oracle("strategy: do not accept $189,100; act before Oct 31", "true", "exact", "strategy_memo.md")
    c.rubric("Pushback answered: why pleading a waived claim hurts; what survives")
    return c.finish()
